import{_ as l,l as n,o as e,c as o,v as t,p as s,x as i,d as E,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"HML Devil","description":"","frontmatter":{"title":"HML Devil","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hml-devil.md","filePath":"quant/hml-devil.md","lastUpdated":1789023840000}'),p={name:"quant/hml-devil.md"};function B(d,a,M,D,c,u){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="hml-devil" tabindex="-1">HML Devil <a class="header-anchor" href="#hml-devil" aria-label="Permalink to &quot;HML Devil&quot;">​</a></h1><div class="epigraph"><p>账面仍用滞后财报，价格改成每月最新市值；只改这一处细节，价值与动量的负相关会尖锐得多，组合的时效也完全不像每年 6 月才重构的 HML。</p><footer>—— Asness &amp; Frazzini, The Devil in HML&#39;s Details, Journal of Portfolio Management, 2013</footer></div><p><a href="/quant/value-factors">价值：BM / EP / CF</a> 写过三种会计映射，并点到 HML Devil 是「价格改成月度更新」。本篇只写这一处细节：Fama–French 的 HML 用上一年 12 月底市值当 B/M 的分母，次年 6 月才换仓，价格最多陈旧一年半；Asness–Frazzini 保持账面滞后以避免前视，但分母用<strong>当期价格</strong>。魔鬼不在新的基本面，而在价值因子里混进了多少已经实现的动量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 HML 的 B/M 分子是财政年度 \\(t-1\\) 的账面股权，分母是 \\(t-1\\) 年 12 月市值，组合在 \\(t\\) 年 6 月形成。到了 \\(t\\) 年 5 月，分母已经是五到十七个月前的价格。这段窗口里跌深的股票，真实当期 B/M 已经更高，却仍按旧价格待在成长组或中间组；涨多的股票真实已经变贵，却仍待在价值组。于是「价值」里掺进了<strong>反动量</strong>：HML 会被动做多最近的输家、做空最近的赢家，与 <a href="/quant/momentum-wml">WML</a> 的负相关被钝化，有时甚至看起来像轻微正相关。</p><p>若研究问题是「便宜相对于贵是否有溢价」，陈旧价格把「曾经便宜」和「现在便宜」混在一起。若研究问题是「价值与动量能否做成互补的两条腿」，陈旧价格会让你低估负相关、高估单独持有 HML 的分散化。Devil 要测量的就是：把分母换成最近市值之后，价值溢价还在不在，以及它与动量的关系变成什么样。</p><h3 id="陈旧价格不是「更稳健」-是另一种策略" tabindex="-1">陈旧价格不是「更稳健」，是另一种策略 <a class="header-anchor" href="#陈旧价格不是「更稳健」-是另一种策略" aria-label="Permalink to &quot;陈旧价格不是「更稳健」，是另一种策略&quot;">​</a></h3><p>有人把 6 月重构当成保守：财务滞后、避免前视。财务滞后是必要的，价格滞后不是。账面必须等年报；价格每天可观测。把可观测的价格故意冻结在 12 月，等于在价值信号上叠了一段已实现收益。这可以降低换手，也可以让 HML 在动量崩溃时看起来更稳——因为它已经不像在做空赢家。稳健来自风格混杂，不是来自更好的价值定义。</p><p><span class="marginnote">Devil 仍用滞后账面。用未公布年报的账面、再配上最新价格，是前视，不是 Devil。AQR 的公开序列与 Ken French 的 HML 对不上，首先应查价格日期，而不是先怀疑自己的市值口径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每年更新账面 \\(B_{i,t}\\)，每月用当时市值 \\(M_{i,t}\\) 算</p> \\[\\mathrm{B/M}^{\\mathrm{Devil}}_{i,t}=\\frac{B_{i,\\mathrm{lag}}}{M_{i,t}}. \\]<p>排序、NYSE 分位、规模 2×3、价值加权多空，与 <a href="/quant/ff3">HML</a> 相同，只换排序键的时效。记标准因子为 \\(\\mathrm{HML}^{\\mathrm{FF}}\\)，月度价格版为 \\(\\mathrm{HML}^{\\mathrm{Devil}}\\)。两者相关高但不是 1；后者与 12−1 动量的相关显著更负。实务上还可以对行业中性，或改用 E/P、CF/P 的当期价格版——原则相同：流量或存量滞后，价格不滞后。</p><p>诊断应同时报告：与 \\(\\mathrm{HML}^{\\mathrm{FF}}\\) 的相关、与 WML 的相关、换手、以及把两者一起放进回归时各自的 α。若 \\(\\mathrm{HML}^{\\mathrm{Devil}}\\) 的三因子 α 来自它更及时地加仓暴跌股，那要检查是否可交易：暴跌后的流动性、借券与反转。</p><h3 id="价值-动量组合在细节上才成立" tabindex="-1">价值-动量组合在细节上才成立 <a class="header-anchor" href="#价值-动量组合在细节上才成立" aria-label="Permalink to &quot;价值-动量组合在细节上才成立&quot;">​</a></h3><p>Asness 等人后来在<a href="/quant/value-momentum-everywhere">跨资产价值与动量</a>里强调两条腿负相关、合成夏普更高。负相关的强度取决于价值是否用当期价格。用 French 的 HML 去做「价值加动量」，分散化会被高估或低估，取决于样本段里陈旧价格帮了谁。正确的做法是：价值腿与动量腿在<strong>同一时效哲学</strong>下构造——要么都用月度信号，要么明确承认 HML 里含反转/反动量。</p>',16)),(e(),s(m,null,{default:i(()=>[h(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E6%BB%9E%E5%90%8E%E8%B4%A6%E9%9D%A2%20B%22%5D%20--%3E%20FF%5B%22%E5%88%86%E6%AF%8D%EF%BC%9A%E5%8E%BB%E5%B9%B412%E6%9C%88%E5%B8%82%E5%80%BC%22%5D%0A%20%20B%20--%3E%20DV%5B%22%E5%88%86%E6%AF%8D%EF%BC%9A%E5%BD%93%E6%9C%88%E5%B8%82%E5%80%BC%22%5D%0A%20%20FF%20--%3E%20HML%5B%22HML%20FF%EF%BC%9A6%E6%9C%88%E9%87%8D%E6%9E%84%22%5D%0A%20%20DV%20--%3E%20DEV%5B%22HML%20Devil%EF%BC%9A%E6%9C%88%E5%BA%A6%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20HML%20--%3E%20MIX%5B%22%E6%B7%B7%E5%85%A5%E5%B7%B2%E5%AE%9E%E7%8E%B0%E5%8A%A8%E9%87%8F%22%5D%0A%20%20DEV%20--%3E%20NEG%5B%22%E4%B8%8E%20WML%20%E6%9B%B4%E8%B4%9F%E7%9B%B8%E5%85%B3%22%5D%0A%20%20MIX%20--%3E%20PORT%5B%22%E4%BB%B7%E5%80%BC%2B%E5%8A%A8%E9%87%8F%E9%85%8D%E7%BD%AE%22%5D%0A%20%20NEG%20--%3E%20PORT%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价格更新之后，价值变成对「当前倍数」下注。行为上，这更接近对过度外推的纠正：刚被打下来的高倍数会更快进入多头。风险上，当期高 B/M 更接近困境与杠杆的实时度量，对信贷条件更敏感。两种叙事都预测 Devil 的换手更高、左尾与动量更对冲、与动量同时去杠杆时尾部更齐。</p><p>陈旧 HML 在动量行情里会「躺赢」一段时间：赢家继续涨，而它还拿着旧的便宜标签做空成长——其实空的是已经涨起来、账面仍显示成长的名字，逻辑混乱。Devil 强迫你在涨价的同时把名字从价值组拿掉，溢价若还在，才更像倍数本身被定价。</p><h3 id="与-e-p、cf-p-的时效要对齐" tabindex="-1">与 E/P、CF/P 的时效要对齐 <a class="header-anchor" href="#与-e-p、cf-p-的时效要对齐" aria-label="Permalink to &quot;与 E/P、CF/P 的时效要对齐&quot;">​</a></h3><p>E/P、CF/P 若用 TTM 与当期价格，本来就比年度 HML 快。用 Devil 的 B/M 去和「快 E/P」比，比的是会计映射；用 FF 的 B/M 去和快 E/P 比，比的是时效加映射。行业中性、企业价值口径等取舍见价值专文。这里只要求：同一张表里的价值度量，价格日期必须写明。</p><p><span class="marginnote">月度价格会让价值在崩盘当月大幅加仓银行与周期股。这是特征，不是 bug。回测若再叠加「当月最低价成交」，会把流动性幻觉写进 Devil。应用次月开盘或成交量加权价格，并扣掉涨跌停。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>换手明显高于 6 月 HML，容量受大盘约束仍好于动量，但已不是「几乎免费」。税务与冲击成本在月度再平衡下必须进净值。国际样本上，财报滞后规则不同，Devil 的账面日期要按当地披露日历，而不是统一 6 月。A 股壳与 ST 的市值跳跃会让当期 B/M 爆炸，需缩尾。</p><p>不要把 Devil 叫做新的风险因子。不要把它与 <a href="/quant/ff3">HML</a> 同时放进回归还解释两个价值 α——共线。不要声称「价值已死」，若你检验的是 FF 的陈旧 HML 在 2010 年代对成长泡沫的滞后；反之，也不要用 Devil 在某几年的强势证明价值永远有效。时效选择是研究设计，应写进说明书。</p><p><span class="marginnote">出处：Asness &amp; Frazzini, <em>The Devil in HML&#39;s Details</em>, Journal of Portfolio Management, 2013。标准 HML 见 Fama &amp; French, 1993。跨资产的价值-动量负相关见 Asness, Moskowitz &amp; Pedersen, 2013。不要给 Devil 伪造一个 French 数据库代码。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HML Devil 保持滞后账面，把 B/M 分母换成月度最新市值。</li><li>标准 HML 因价格陈旧而混入反动量，与 WML 的负相关被钝化。</li><li>时效对齐之后，价值与动量才是可配置的互补腿。</li><li>换手、崩盘加仓与成交假设属于策略定义，不是附录。</li><li>出处：Asness &amp; Frazzini, Journal of Portfolio Management, 2013。</li></ul>',12))])}const F=l(p,[["render",B]]);export{f as __pageData,F as default};
